{-| @Backend.Runtime.Host.TimeParse — text read as an instant with a pattern, as `Pudu.Eval.Clock` answers it under the fixed English locale. -}
module Pudu.Backend.Runtime.Host.TimeParse (hostTimeParseParts) where

import Data.Text (Text)

{-| Each part: its name, the parts it needs, and its lines. -}
hostTimeParseParts :: [(Text, [Text], [Text])]
hostTimeParseParts =
  [ ("host_parse_time", ["host_calendar", "host_done", "kernel_int", "make", "text_concat", "text_literal",
        "int_to_wide", "wide_add_math", "wide_magnitude", "wide_multiply_math"],
      [ "/* One specifier's share of the text, and the reading in progress: the"
      , "   pattern with its composite specifiers written out, the text, the parts"
      , "   read so far, and how many whole readings built an instant. */"
      , "typedef struct { char kind; char text[40]; } pudu_host_part;"
      , "typedef struct {"
      , "  const unsigned char *pattern, *text;"
      , "  size_t pattern_length, text_length;"
      , "  pudu_host_part parts[64];"
      , "  int built, reached;"
      , "  pudu_wide_int value;"
      , "} pudu_host_reading;"
      , "static inline int pudu_host_space(unsigned char byte) { return byte == ' ' || (byte >= 9 && byte <= 13); }"
      , "static inline int pudu_host_digit(unsigned char byte) { return byte >= '0' && byte <= '9'; }"
      , "static inline int pudu_host_letter(unsigned char byte) { return (byte >= 'a' && byte <= 'z') || (byte >= 'A' && byte <= 'Z'); }"
      , "static inline unsigned char pudu_host_upper(unsigned char byte) { return byte >= 'a' && byte <= 'z' ? (unsigned char)(byte - 32) : byte; }"
      , "static int pudu_host_same_word(const char *left, const char *right) {"
      , "  for (; *left != 0 && *right != 0; ++left, ++right) if (pudu_host_upper((unsigned char)*left) != pudu_host_upper((unsigned char)*right)) return 0;"
      , "  return *left == 0 && *right == 0;"
      , "}"
      , "/* A whole number as written, or nothing when it is not one or does not fit. */"
      , "static int pudu_host_read_bounded_whole(const char *text, int64_t limit, int64_t *value) {"
      , "  int negative = text[0] == '-';"
      , "  const char *digits = text + negative;"
      , "  int64_t total = 0;"
      , "  if (*digits == 0) return 0;"
      , "  for (; *digits != 0; ++digits) {"
      , "    if (!pudu_host_digit((unsigned char)*digits)) return 0;"
      , "    int digit = *digits - '0';"
      , "    if (total > (limit - digit) / 10) return 0;"
      , "    total = total * 10 + digit;"
      , "  }"
      , "  *value = negative ? -total : total;"
      , "  return 1;"
      , "}"
      , "static int pudu_host_read_whole(const char *text, int64_t *value) {"
      , "  return pudu_host_read_bounded_whole(text, INT64_C(999999999999999), value);"
      , "}"
      , "static int pudu_host_read_within(const char *text, int64_t least, int64_t most, int64_t *value) {"
      , "  return pudu_host_read_whole(text, value) && *value >= least && *value <= most;"
      , "}"
      , "static int pudu_host_word_index(const char *text, const char *const *words, int count, size_t length) {"
      , "  for (int index = 0; index < count; ++index) {"
      , "    char word[16];"
      , "    size_t size = length == 0 ? strlen(words[index]) : length;"
      , "    memcpy(word, words[index], size);"
      , "    word[size] = 0;"
      , "    if (pudu_host_same_word(text, word)) return index;"
      , "  }"
      , "  return -1;"
      , "}"
      , "/* The offset in minutes a written zone stands for. */"
      , "static int pudu_host_read_offset(const char *text, int64_t *minutes) {"
      , "  size_t length = strlen(text);"
      , "  const char *tail = text + 3;"
      , "  if (length == 6 && text[3] == ':') tail = text + 4;"
      , "  else if (length != 5) return 0;"
      , "  if ((text[0] != '+' && text[0] != '-') || !pudu_host_digit((unsigned char)text[1]) || !pudu_host_digit((unsigned char)text[2])"
      , "      || !pudu_host_digit((unsigned char)tail[0]) || !pudu_host_digit((unsigned char)tail[1])) return 0;"
      , "  *minutes = (text[0] == '-' ? -1 : 1) * (60 * ((text[1] - '0') * 10 + (text[2] - '0')) + (tail[0] - '0') * 10 + (tail[1] - '0'));"
      , "  return 1;"
      , "}"
      , "/* The instant the parts name, in milliseconds since the start of 1970. A"
      , "   missing date is the first day of 1970, a missing time midnight, a missing"
      , "   zone no offset. Parts that name no day or no time build nothing. */"
      , "static int pudu_host_build_instant(const pudu_host_part *parts, int count, pudu_wide_int *instant) {"
      , "  static const char *const zones[] = {\"UT\", \"GMT\", \"EST\", \"EDT\", \"CST\", \"CDT\", \"MST\", \"MDT\", \"PST\", \"PDT\"};"
      , "  static const int offsets[] = {0, 0, -300, -240, -360, -300, -420, -360, -480, -420};"
      , "  int64_t century = 0, of_century = 70, month_day = 1, week_day = 4, year, days = 0, number, minutes = 0;"
      , "  int64_t hour = 0, minute = 0, second = 0, pico = 0, whole, rest, units;"
      , "  int64_t unit_millis = INT64_C(146097) * 86400000;"
      , "  int has_century = 0, anchor = 0, anchor_value = 1, index;"
      , "  for (index = 0; index < count; ++index) {"
      , "    const char *text = parts[index].text;"
      , "    int found;"
      , "    switch (parts[index].kind) {"
      , "      case 'C': case 'f':"
      , "        if (!pudu_host_read_whole(text, &number)) return 0;"
      , "        century = number; has_century = 1; break;"
      , "      case 'Y': case 'G':"
      , "        if (!pudu_host_read_whole(text, &number)) return 0;"
      , "        century = pudu_host_floor_div(number, 100); has_century = 1; of_century = pudu_host_floor_mod(number, 100); break;"
      , "      case 'y': case 'g':"
      , "        if (!pudu_host_read_whole(text, &number)) return 0;"
      , "        of_century = number; break;"
      , "      case 'B': case 'b':"
      , "        found = pudu_host_word_index(text, pudu_host_months, 12, parts[index].kind == 'b' ? 3 : 0);"
      , "        if (found < 0) return 0;"
      , "        if (anchor == 0) { anchor = 1; anchor_value = found + 1; }"
      , "        break;"
      , "      case 'm':"
      , "        if (!pudu_host_read_within(text, 1, 12, &number)) return 0;"
      , "        if (anchor == 0) { anchor = 1; anchor_value = (int)number; }"
      , "        break;"
      , "      case 'd': case 'e':"
      , "        if (!pudu_host_read_within(text, 1, 31, &number)) return 0;"
      , "        month_day = number; break;"
      , "      case 'V': case 'U': case 'W':"
      , "        if (!pudu_host_read_within(text, parts[index].kind == 'V' ? 1 : 0, 53, &number)) return 0;"
      , "        if (anchor == 0) { anchor = parts[index].kind == 'V' ? 3 : parts[index].kind == 'U' ? 4 : 5; anchor_value = (int)number; }"
      , "        break;"
      , "      case 'u':"
      , "        if (!pudu_host_read_within(text, 1, 7, &number)) return 0;"
      , "        week_day = number; break;"
      , "      case 'a': case 'A':"
      , "        found = pudu_host_word_index(text, pudu_host_weekdays, 7, parts[index].kind == 'a' ? 3 : 0);"
      , "        if (found < 0) return 0;"
      , "        week_day = found == 0 ? 7 : found; break;"
      , "      case 'w':"
      , "        if (!pudu_host_read_within(text, 0, 6, &number)) return 0;"
      , "        week_day = number == 0 ? 7 : number; break;"
      , "      case 'j':"
      , "        if (!pudu_host_read_within(text, 1, 366, &number)) return 0;"
      , "        if (anchor == 0) { anchor = 2; anchor_value = (int)number; }"
      , "        break;"
      , "      case 'P': case 'p':"
      , "        if (pudu_host_same_word(text, \"AM\")) hour = hour % 12;"
      , "        else if (pudu_host_same_word(text, \"PM\")) hour = hour < 12 ? hour + 12 : hour;"
      , "        else return 0;"
      , "        break;"
      , "      case 'H': case 'k':"
      , "        if (!pudu_host_read_within(text, 0, 23, &hour)) return 0;"
      , "        break;"
      , "      case 'I': case 'l':"
      , "        if (!pudu_host_read_within(text, 1, 12, &hour)) return 0;"
      , "        break;"
      , "      case 'M':"
      , "        if (!pudu_host_read_within(text, 0, 59, &minute)) return 0;"
      , "        break;"
      , "      case 'S':"
      , "        if (!pudu_host_read_within(text, 0, 60, &second)) return 0;"
      , "        pico = 0; break;"
      , "      case 'q': case 'Q':"
      , "        if (parts[index].kind == 'Q' && text[0] == 0) break;"
      , "        pico = 0;"
      , "        for (found = 0; found < 12; ++found) pico = pico * 10 + (text[found] != 0 && found < (int)strlen(text) ? text[found] - '0' : 0);"
      , "        break;"
      , "      case 'z':"
      , "        if (!pudu_host_read_offset(text, &minutes)) return 0;"
      , "        break;"
      , "      case 'Z':"
      , "        if (pudu_host_read_offset(text, &minutes)) break;"
      , "        found = pudu_host_word_index(text, zones, 10, 0);"
      , "        if (found >= 0) { minutes = offsets[found]; break; }"
      , "        if (strcmp(text, \"UTC\") == 0) { minutes = 0; break; }"
      , "        if (text[0] != 0 && text[1] == 0) {"
      , "          unsigned char letter = pudu_host_upper((unsigned char)text[0]);"
      , "          if (letter >= 'A' && letter <= 'I') { minutes = 60 * (1 + letter - 'A'); break; }"
      , "          if (letter >= 'K' && letter <= 'M') { minutes = 60 * (10 + letter - 'K'); break; }"
      , "          if (letter >= 'N' && letter <= 'Y') { minutes = 60 * ('N' - letter - 1); break; }"
      , "          if (letter == 'Z') { minutes = 0; break; }"
      , "        }"
      , "        return 0;"
      , "      case 's': break;"
      , "      default: return 0;"
      , "    }"
      , "  }"
      , "  year = 100 * (has_century ? century : of_century >= 69 ? 19 : 20) + of_century;"
      , "  /* Every calendar cycle contains a whole number of weeks. Keep the"
      , "     date arithmetic near the epoch and restore the displaced days at the end. */"
      , "  units = (year - 1970) / 400;"
      , "  year -= units * 400;"
      , "  if (anchor <= 1) {"
      , "    if (month_day > pudu_host_month_length(year, anchor_value)) return 0;"
      , "    days = pudu_host_days_from_civil(year, anchor_value, (int)month_day);"
      , "  } else if (anchor == 2) {"
      , "    if (anchor_value > (pudu_host_leap_year(year) ? 366 : 365)) return 0;"
      , "    days = pudu_host_days_from_civil(year, 1, 1) + anchor_value - 1;"
      , "  } else if (anchor == 3) {"
      , "    int64_t fourth = pudu_host_days_from_civil(year, 1, 4), week_year;"
      , "    int week;"
      , "    days = fourth - pudu_host_floor_mod(fourth + 3, 7) + 7 * (int64_t)(anchor_value - 1) + week_day - 1;"
      , "    pudu_host_week_date(days, &week_year, &week);"
      , "    if (week_year != year || week != anchor_value) return 0;"
      , "  } else {"
      , "    int64_t first = pudu_host_days_from_civil(year, 1, 1);"
      , "    int64_t of_year = pudu_host_floor_mod((anchor == 4 ? 4 : 5) - (first + 40587), 7) + 7 * (int64_t)(anchor_value - 1)"
      , "      + (anchor == 4 ? pudu_host_floor_mod(week_day, 7) : week_day - 1);"
      , "    if (of_year < 0 || of_year > (pudu_host_leap_year(year) ? 365 : 364)) return 0;"
      , "    days = first + of_year;"
      , "  }"
      , "  whole = days * 86400 + hour * 3600 + minute * 60 + second - minutes * 60;"
      , "  for (index = 0; index < count; ++index) {"
      , "    if (parts[index].kind != 's') continue;"
      , "    if (!pudu_host_read_bounded_whole(parts[index].text, INT64_MAX, &units)) return 0;"
      , "    unit_millis = 1000;"
      , "    whole = 0;"
      , "  }"
      , "  rest = pico / 1000000000;"
      , "  pico -= rest * 1000000000;"
      , "  if (pico * 2 > 1000000000 || (pico * 2 == 1000000000 && rest % 2 != 0)) rest += 1;"
      , "  /* Bounded fields keep either scaled contribution within the wide carrier. */"
      , "  *instant = pudu_int_to_wide(pudu_kernel_int(whole * 1000 + rest));"
      , "  if (units != 0) {"
      , "    pudu_wide_int displacement = pudu_int_to_wide(pudu_kernel_int(units));"
      , "    pudu_wide_int scale = pudu_int_to_wide(pudu_kernel_int(unit_millis));"
      , "    *instant = pudu_wide_add_math(pudu_wide_multiply_math(displacement, scale).value, *instant).value;"
      , "  }"
      , "  return 1;"
      , "}"
      , "static void pudu_host_read_from(pudu_host_reading *reading, size_t at, size_t from, int count);"
      , "static void pudu_host_read_part(pudu_host_reading *reading, size_t at, size_t next, int count, char kind,"
      , "    const char *first, size_t first_length, const unsigned char *second, size_t second_length, const unsigned char *third, size_t third_length) {"
      , "  pudu_host_part *part;"
      , "  if (count >= 64) return;"
      , "  part = &reading->parts[count];"
      , "  part->kind = first_length + second_length + third_length < sizeof part->text ? kind : '?';"
      , "  part->text[0] = 0;"
      , "  if (part->kind != '?') {"
      , "    if (first_length != 0) memcpy(part->text, first, first_length);"
      , "    if (second_length != 0) memcpy(part->text + first_length, second, second_length);"
      , "    if (third_length != 0) memcpy(part->text + first_length + second_length, third, third_length);"
      , "    part->text[first_length + second_length + third_length] = 0;"
      , "  }"
      , "  pudu_host_read_from(reading, at, next, count + 1);"
      , "}"
      , "/* The runs of digits a number may take from here. Padding 0 takes exactly"
      , "   the width, 1 takes any run, 2 skips spaces first and then takes any run. */"
      , "typedef struct { size_t start, least, most; } pudu_host_run;"
      , "static int pudu_host_digit_runs(const pudu_host_reading *reading, size_t from, int padding, size_t width, int maximal, int empty, pudu_host_run *run) {"
      , "  size_t length = 0;"
      , "  if (padding == 2) while (from < reading->text_length && pudu_host_space(reading->text[from])) from += 1;"
      , "  while (from + length < reading->text_length && pudu_host_digit(reading->text[from + length])) length += 1;"
      , "  run->start = from;"
      , "  if (padding == 0) {"
      , "    if (length < width || (width == 0 && !empty)) return 0;"
      , "    run->least = run->most = width;"
      , "    return 1;"
      , "  }"
      , "  run->most = length;"
      , "  run->least = maximal ? length : empty ? 0 : 1;"
      , "  return run->least <= run->most && (empty || length != 0);"
      , "}"
      , "static void pudu_host_read_zone(pudu_host_reading *reading, size_t at, size_t from, int count, char kind, int padding) {"
      , "  pudu_host_run hours, minutes;"
      , "  if (from >= reading->text_length || (reading->text[from] != '+' && reading->text[from] != '-')) return;"
      , "  if (!pudu_host_digit_runs(reading, from + 1, padding, 2, 0, 0, &hours)) return;"
      , "  for (size_t taken = hours.least; taken <= hours.most; ++taken) {"
      , "    size_t after = hours.start + taken;"
      , "    for (int colon = 0; colon < 2; ++colon) {"
      , "      if (colon && !(after < reading->text_length && reading->text[after] == ':')) continue;"
      , "      if (!pudu_host_digit_runs(reading, after + (size_t)colon, padding, 2, 0, 0, &minutes)) continue;"
      , "      for (size_t more = minutes.least; more <= minutes.most; ++more)"
      , "        pudu_host_read_part(reading, at, minutes.start + more, count, kind, (const char *)reading->text + from, 1,"
      , "          reading->text + hours.start, taken, reading->text + minutes.start, more);"
      , "    }"
      , "  }"
      , "}"
      , "static void pudu_host_read_specifier(pudu_host_reading *reading, char kind, int asked, size_t at, size_t from, int count) {"
      , "  const unsigned char *text = reading->text;"
      , "  size_t length = reading->text_length, width = 2;"
      , "  int padding = 0, signs = 0;"
      , "  pudu_host_run run;"
      , "  switch (kind) {"
      , "    case 'Y': case 'G': width = 4; padding = 2; signs = 1; break;"
      , "    case 'C': case 'f': padding = 2; signs = 1; break;"
      , "    case 'e': case 'k': case 'l': padding = 2; break;"
      , "    case 'j': width = 3; break;"
      , "    case 'y': case 'g': case 'm': case 'd': case 'V': case 'U': case 'W': case 'H': case 'I': case 'M': case 'S': break;"
      , "    case 'B': case 'b': case 'a': case 'A': {"
      , "      const char *const *words = kind == 'B' || kind == 'b' ? pudu_host_months : pudu_host_weekdays;"
      , "      int total = kind == 'B' || kind == 'b' ? 12 : 7;"
      , "      for (int index = 0; index < total; ++index) {"
      , "        size_t size = kind == 'b' || kind == 'a' ? 3 : strlen(words[index]), same = 0;"
      , "        while (same < size && from + same < length && pudu_host_upper(text[from + same]) == pudu_host_upper((unsigned char)words[index][same])) same += 1;"
      , "        if (same == size) pudu_host_read_part(reading, at, from + size, count, kind, (const char *)text + from, size, NULL, 0, NULL, 0);"
      , "      }"
      , "      return;"
      , "    }"
      , "    case 'P': case 'p':"
      , "      if (from + 2 <= length && (pudu_host_upper(text[from]) == 'A' || pudu_host_upper(text[from]) == 'P') && pudu_host_upper(text[from + 1]) == 'M')"
      , "        pudu_host_read_part(reading, at, from + 2, count, kind, (const char *)text + from, 2, NULL, 0, NULL, 0);"
      , "      return;"
      , "    case 'u': case 'w':"
      , "      if (from < length && text[from] >= (kind == 'u' ? '1' : '0') && text[from] <= (kind == 'u' ? '7' : '6'))"
      , "        pudu_host_read_part(reading, at, from + 1, count, kind, (const char *)text + from, 1, NULL, 0, NULL, 0);"
      , "      return;"
      , "    case 'q': case 'Q': {"
      , "      size_t after;"
      , "      if (kind == 'Q') {"
      , "        if (!(from < length && text[from] == '.')) { pudu_host_read_part(reading, at, from, count, kind, \"\", 0, NULL, 0, NULL, 0); return; }"
      , "        from += 1;"
      , "      }"
      , "      if (!pudu_host_digit_runs(reading, from, asked == 3 ? 0 : asked == 2 ? 3 : 1, 12, 1, 1, &run)) return;"
      , "      after = run.start + run.most;"
      , "      if (asked == 2) while (after < length && pudu_host_space(text[after])) after += 1;"
      , "      pudu_host_read_part(reading, at, after, count, kind, (const char *)text + run.start, run.most, NULL, 0, NULL, 0);"
      , "      return;"
      , "    }"
      , "    case 'z': pudu_host_read_zone(reading, at, from, count, kind, asked == 1 ? 1 : asked == 2 ? 2 : 0); return;"
      , "    case 'Z': {"
      , "      size_t letters = 0;"
      , "      while (from + letters < length && pudu_host_letter(text[from + letters])) letters += 1;"
      , "      if (letters != 0) pudu_host_read_part(reading, at, from + letters, count, kind, (const char *)text + from, letters, NULL, 0, NULL, 0);"
      , "      else pudu_host_read_zone(reading, at, from, count, kind, asked == 1 ? 1 : asked == 2 ? 2 : 0);"
      , "      return;"
      , "    }"
      , "    case 's': {"
      , "      size_t sign = from < length && text[from] == '-' ? 1 : 0, digits = 0;"
      , "      while (from + sign + digits < length && pudu_host_digit(text[from + sign + digits])) digits += 1;"
      , "      if (digits != 0) pudu_host_read_part(reading, at, from + sign + digits, count, kind, (const char *)text + from, sign + digits, NULL, 0, NULL, 0);"
      , "      return;"
      , "    }"
      , "    default: return;"
      , "  }"
      , "  if (asked != 0) padding = asked == 1 ? 1 : asked == 2 ? 2 : 0;"
      , "  for (int sign = 0; sign <= signs; ++sign) {"
      , "    if (sign && !(from < length && text[from] == '-')) continue;"
      , "    if (!pudu_host_digit_runs(reading, from + (size_t)sign, padding, width, 0, 0, &run)) continue;"
      , "    for (size_t taken = run.least; taken <= run.most; ++taken)"
      , "      pudu_host_read_part(reading, at, run.start + taken, count, kind, \"-\", (size_t)sign, text + run.start, taken, NULL, 0);"
      , "  }"
      , "}"
      , "static void pudu_host_read_from(pudu_host_reading *reading, size_t at, size_t from, int count) {"
      , "  const unsigned char *pattern = reading->pattern, *text = reading->text;"
      , "  size_t length = reading->pattern_length;"
      , "  if (reading->built > 1) return;"
      , "  if (at == length) {"
      , "    pudu_wide_int instant;"
      , "    reading->reached = 1;"
      , "    while (from < reading->text_length && pudu_host_space(text[from])) from += 1;"
      , "    if (from == reading->text_length && pudu_host_build_instant(reading->parts, count, &instant)) { reading->built += 1; reading->value = instant; }"
      , "    return;"
      , "  }"
      , "  if (pattern[at] == '%') {"
      , "    size_t next = at + 1;"
      , "    int asked = 0;"
      , "    if (next < length && pattern[next] == '-') { asked = 1; next += 1; }"
      , "    else if (next < length && pattern[next] == '_') { asked = 2; next += 1; }"
      , "    else if (next < length && pattern[next] == '0') { asked = 3; next += 1; }"
      , "    if (next < length && pattern[next] == 'E') next += 1;"
      , "    if (next >= length) { pudu_host_read_from(reading, length, from, count); return; }"
      , "    if (pattern[next] == '%') {"
      , "      if (from < reading->text_length && text[from] == '%') pudu_host_read_from(reading, next + 1, from + 1, count);"
      , "      return;"
      , "    }"
      , "    pudu_host_read_specifier(reading, (char)pattern[next], asked, next + 1, from, count);"
      , "    return;"
      , "  }"
      , "  if (pudu_host_space(pattern[at])) {"
      , "    if (!(from < reading->text_length && pudu_host_space(text[from]))) return;"
      , "    from += 1;"
      , "    if (!(at + 1 < length && pudu_host_space(pattern[at + 1]))) while (from < reading->text_length && pudu_host_space(text[from])) from += 1;"
      , "    pudu_host_read_from(reading, at + 1, from, count);"
      , "    return;"
      , "  }"
      , "  if (from < reading->text_length && pudu_host_upper(text[from]) == pudu_host_upper(pattern[at])) pudu_host_read_from(reading, at + 1, from + 1, count);"
      , "}"
      , "/* Text read as an instant with a pattern. Exactly one reading of the whole"
      , "   text must build an instant; none or several is a refusal naming the pattern. */"
      , "static pudu_int pudu_host_parse_time(pudu_text pattern, pudu_text text) {"
      , "  pudu_host_words flat = {NULL, 0, 0};"
      , "  pudu_host_reading *reading = pudu_host_grow(NULL, sizeof *reading);"
      , "  size_t index = 0, spaces = 0;"
      , "  pudu_word128 magnitude;"
